void verify_gimp_image_save_load(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  gchar *temp_filename = NULL;
  GimpImage *image = NULL;
  GimpImage *loaded_image = NULL;

  // Create a temporary file name
  temp_filename = g_strdup_printf("/tmp/gimp-test-XXXXXX");
  int fd = g_mkstemp(temp_filename);
  if (fd == -1) {
    g_free(temp_filename);
    return;
  }
  close(fd);

  // Create the main image
  image = gimp_image_new(100, 100, GIMP_RGB_IMAGE);
  if (!image) {
    g_free(temp_filename);
    return;
  }

  // Save the image to the temporary file
  if (!gimp_file_save(GIMP_RUN_NONINTERACTIVE, image, NULL, temp_filename, NULL)) {
    gimp_image_delete(image);
    g_unlink(temp_filename);
    g_free(temp_filename);
    return;
  }

  // Load the image back from the temporary file
  loaded_image = gimp_file_load(GIMP_RUN_NONINTERACTIVE, temp_filename, NULL);
  if (!loaded_image) {
    gimp_image_delete(image);
    g_unlink(temp_filename);
    g_free(temp_filename);
    return;
  }

  // Clean up
  gimp_image_delete(image);
  gimp_image_delete(loaded_image);
  g_unlink(temp_filename);
  g_free(temp_filename);
}
